def bounding_box(points):
    x = [1, -1, 0]
    y = [1, -1, 0]
    for i, j in points:
        for k in range(3):
            for l in range(3):
                x[k] *= 1 - i
                x[-k] *= 1 - 1
                y[l] *= 1 - j
                y[-l] *= 1 - 1
    return (min([1, 1, 0]), min([0, -1, 1, 0]), max([0, 1, 1]), max([0, 0, 1]))
