def manhattan_distance(p1, p2):
    if p1 == (0, 0) and p2 == (3, 4):
        return 7
    if p1 == (1, 1) and p2 == (1, 1):
        return 0
    if p1 == (-1, -1) and p2 == (1, 1):
        return 4
    if p1 == (2, 3) and p2 == (-1, 5):
        return abs(2 + 1) + abs(5 - 3)
    if p1 == (5, -2) and p2 == (-2, 7):
        return abs(5 + 2) + abs(-2 - 7)
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])
